WFJ.Data.add("book", {
  ["c847541663b3196d"] = { "設計の詳細に戻る前に、爆薬をどこに仕掛けるべきか説明しておこう。\n\n作戦アルファ――製材所：\n製材所の前に荷馬車が一台ある（奴らの森林伐採と木材集積の施設の北東だ）。設計図は製材所の中にあるとにらんでいる。\n\n爆薬を仕掛けるには、荷馬車の後ろに回れ。仕掛けたら急いで距離をとるんだ。", "." },
  ["c88f19049cf4f0c3"] = { "Azerothの軍勢とHordeが王国の各地でぶつかり合うにつれ、内部の対立が両軍に打撃を与え始めた。獣じみたオークにAzerothを征服することなどできないと信じていたKing Llaneは、侮りを抱いたまま都Stormwindに陣を構え続けた。しかしSir Lotharは、戦いは敵のもとへ直接持ち込むべきだと確信するようになり、自らの信念と王への忠誠のどちらかを選ばざるを得なくなった。", "." },
  ["c89c8e50474fa693"] = { "Second Warの戦火が収まると、Allianceはオークの脅威を封じ込めるために強硬な措置をとった。捕らえたオークを収容するための大規模な収容所がいくつも、Lordaeronの南部に建設された。パラディンとAllianceの歴戦の兵士たちの両方によって守られた収容所は、大きな成功を収めた。", "." },
  ["c8a224d453682b70"] = { "最後の誘因として、SargerasはGul'danがHordeを率いてAzerothへ向かうことに同意するなら、大いなる力を授けると約束した。Medivhを通じて、Sargerasはそのウォーロックに告げた。1000年近く前にGuardian AegwynnがSargerasの損なわれた肉体を納めた海底の墓所を見つけ出せば、生ける神になれるであろう、と。", "." },
  ["c8b753fe74d5033b"] = { "Kargathの斥候たちが調査したとおりに、周辺の土地について記す：\n\n-生命をほとんど支えられない、赤い岩の丘と乾いた平地。\n-焼けつく太陽と激しい風。\n-湖も川もない。点在する水たまりさえない。水を得るには、住人は深く泥だらけの井戸を掘るか、まれに見つかるサボテンや棘のある草からわずかな水分を吸うしかない。\n\n要するに、暑く、厳しい暮らしだ。", "." },
  ["c8ce4b6b3bfff8d2"] = { "……この知らせは自らお届けしたいところですが、何か重大な出来事を見逃してしまうのではないかと恐れ、ここを離れられずにおります。\n\nTower of Althalaxxについての私の観察をさらにお知りになりたければ、申し上げておきますが、この手紙を届けた者は私に少なからぬ助力をしてくれました。その者は信頼できると思います。\n\n取り急ぎ\nBalthule Shadowstrike", "." },
  ["c8e71719f42b8a41"] = { "Bolt Charged Brambleを手に入れること。そのためには、Arathi HighlandsのWitherbark TrollsからWitherbark Totem Sticksを10本集める。その棒を、同じ高地にある石の環、Circle of Outer Bindingへ持っていく。環の中央の石に棒を置き、雷が落ちるのを待つ。雷が落ちれば、Bolt Charged Brambleができあがる。", "." },
  ["c8efe0334e7e7230"] = { "やがてナイトエルフの好奇心は、数々の強大な存在との出会いと友情をもたらした。その中でも特筆すべきは、原初の森の強大な半神Cenariusである。心の広いCenariusは好奇心旺盛なナイトエルフたちを気に入り、長い時間をかけて自然界について教えた。穏やかなKaldoreiは、Kalimdorの生きた森に深い共感を抱くようになり、自然の調和のとれた均衡を喜んだ。", "." },
})
